       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_79_v1'
from (values
('127.611.d.1.A',3,'Before making a big purchase, a responsible decision maker lists the choices and compares the likely results of each. This step is called weighing:','["consequences", "guesses", "rumors", "fashions"]'::jsonb,0,'Responsible decisions consider outcomes against personal needs.','original'),
('127.611.d.1.A',4,'Which is the best first step in making a responsible decision that fits your personal needs?','["ask no one", "identify the problem and your needs", "wait for luck", "pick the quickest option"]'::jsonb,1,'Clear needs guide the choice.','original'),
('127.611.d.1.B',3,'A goal such as ''save $500 by June 1'' is measurable because it includes a specific amount and:','["a feeling", "a wish", "a deadline", "a rumor"]'::jsonb,2,'Measurable goals state how much and by when.','original'),
('127.611.d.1.B',4,'Finishing high school is an example of which type of goal for someone planning a career?','["accident", "no goal", "hobby", "short-term goal"]'::jsonb,3,'Short-term goals are reached soon and lead to long-term ones.','original'),
('127.611.d.1.C',3,'Using a planner to schedule homework, chores, and rest is a personal-management skill that boosts:','["productivity", "clutter", "stress only", "delay"]'::jsonb,0,'Planning time helps people get more done.','original'),
('127.611.d.1.C',4,'Breaking a large project into smaller tasks with due dates is a skill called:','["multitasking only", "time management", "avoidance", "procrastination"]'::jsonb,1,'Smaller steps make big jobs manageable.','original'),
('127.611.d.1.D',3,'When two coworkers disagree, an ethical way to resolve the conflict is to:','["shout louder", "spread rumors", "listen and look for a compromise", "give the silent treatment"]'::jsonb,2,'Respectful talk solves problems.','original'),
('127.611.d.1.D',4,'Using ''I'' statements such as ''I feel upset when plans change'' helps resolve conflict by avoiding:','["eye contact", "clear speech", "honest feelings", "blaming the other person"]'::jsonb,3,'I statements describe feelings without accusing.','original'),
('127.611.d.1.E',3,'Wearing clean, neat clothing that fits the setting for a job interview shows:','["appropriate apparel", "carelessness", "indifference", "disrespect"]'::jsonb,0,'Dressing for the setting shows professionalism.','original'),
('127.611.d.1.E',4,'Good grooming and appearance matter in the workplace because they influence others'' first:','["schedules", "impressions", "taxes", "recipes"]'::jsonb,1,'Appearance shapes how people see you.','original'),
('127.611.d.1.F',3,'Getting enough sleep, eating well, and exercising are wellness habits that help people stay:','["tired", "distracted", "productive", "absent"]'::jsonb,2,'Healthy habits support performance.','original'),
('127.611.d.1.F',4,'Poor wellness, such as chronic lack of sleep, can lead to more missed workdays and lower:','["pay stubs", "sleep needs", "commutes", "job performance"]'::jsonb,3,'Health affects work.','original'),
('127.611.d.1.G',3,'Misusing alcohol or drugs can cause lost jobs, health problems, and damaged:','["relationships", "fashions", "weather", "bank rules"]'::jsonb,0,'Substance abuse affects every part of life.','original'),
('127.611.d.1.G',4,'Many employers require drug testing because substance abuse can threaten workplace:','["lunch menus", "safety", "parking", "decor"]'::jsonb,1,'Impairment puts coworkers at risk.','original'),
('127.611.d.1.H',3,'Sewing on a loose button and fixing a small hem are examples of apparel:','["marketing", "disposal", "maintenance and repair", "design"]'::jsonb,2,'Basic repairs keep clothing looking good.','original'),
('127.611.d.1.H',4,'Mending a small tear right away helps clothing last longer and keeps a person looking:','["unprofessional", "untidy", "unprepared", "well groomed"]'::jsonb,3,'Repaired clothes look neat.','original'),
('127.611.d.1.I',3,'Competing in a career and technical student organization event is one way to practice:','["leadership skills", "avoiding teams", "cutting corners", "skipping school"]'::jsonb,0,'Student organizations build leadership.','original'),
('127.611.d.1.I',4,'A student who runs for chapter president is demonstrating leadership by taking on:','["delays", "responsibility", "silence", "rivalry"]'::jsonb,1,'Leaders accept responsibility for the group.','original'),
('127.611.d.1.J',3,'Making eye contact, speaking clearly, and listening carefully are parts of effective:','["isolation", "argument", "communication", "avoidance"]'::jsonb,2,'Good communication involves speaking and listening.','original'),
('127.611.d.1.J',4,'A speaker''s tone of voice, facial expressions, and posture are forms of:','["written communication", "electronic mail", "public records", "nonverbal communication"]'::jsonb,3,'Body language carries meaning.','original'),
('127.611.d.2.A',3,'Setting aside money first for rent and food before buying wants is part of allocating:','["finances", "favors", "calendars", "rumors"]'::jsonb,0,'Decision making guides how money is divided.','original'),
('127.611.d.2.A',4,'Comparing prices at three stores before buying a laptop applies the decision-making process to the use of:','["free time", "limited money", "a loan only", "unlimited money"]'::jsonb,1,'Resources are limited, so choices matter.','original'),
('127.611.d.2.B',3,'A phone app that tracks spending and sets reminders for bills is technology used to manage:','["fashion", "weather", "resources", "hobbies"]'::jsonb,2,'Technology helps track money and time.','original'),
('127.611.d.2.B',4,'Setting up automatic payments for bills helps a consumer avoid:','["paychecks", "savings", "raises", "late fees"]'::jsonb,3,'Automation helps meet due dates.','original'),
('127.611.d.2.C',3,'Buying a reusable water bottle instead of many plastic ones is a sustainable choice that saves resources and:','["reduces waste", "uses more plastic", "raises waste", "adds trash"]'::jsonb,0,'Sustainable buying cuts waste and costs over time.','original'),
('127.611.d.2.C',4,'Choosing durable products that last for years promotes the effective use of:','["advertising", "resources", "impulse", "coupons"]'::jsonb,1,'Longer-lasting goods reduce replacement needs.','original'),
('127.611.d.2.D',3,'A career in consumer services may reward workers with helping people and offers demands such as:','["no deadlines", "no work", "dealing with difficult customers", "no customers"]'::jsonb,2,'Every career has rewards and demands.','original'),
('127.611.d.2.D',4,'A future trend in consumer service careers is the growing use of:','["typewriters", "telegrams", "paper catalogs only", "online customer support"]'::jsonb,3,'Technology changes how service is delivered.','original'),
('127.611.d.2.E',3,'Starting your own personal shopping business is an example of an:','["entrepreneurial opportunity", "tax bracket", "employee benefit", "product recall"]'::jsonb,0,'Entrepreneurs create their own businesses.','original'),
('127.611.d.2.E',4,'Preparation for a consumer service career might include education, certification, and:','["a farm", "customer service experience", "a pilot course", "a boat license"]'::jsonb,1,'Experience prepares workers for service jobs.','original'),
('127.611.d.3.A',3,'A house fire, a job loss, and a serious illness are all examples of types of:','["holidays", "hobbies", "crises", "habits"]'::jsonb,2,'A crisis is an event that disrupts normal life.','original'),
('127.611.d.3.A',4,'A flood that damages a neighborhood is classified as a crisis caused by:','["fashion", "boredom", "personal choice", "natural disaster"]'::jsonb,3,'Crises may be natural, economic, health, or relational.','original'),
('127.611.d.3.B',3,'After a family loses a home to a fire, an appropriate first response is to make sure everyone is safe and then contact:','["emergency or community aid services", "no one", "competitors", "stores only"]'::jsonb,0,'Resources help families recover.','original'),
('127.611.d.3.B',4,'Which technology can help a family manage a crisis by locating shelters or emergency help?','["a pocket watch", "a smartphone app or website", "a paper map from 1990", "a typewriter"]'::jsonb,1,'Technology gives fast access to services.','original'),
('127.611.d.3.C',3,'A crisis such as a parent''s job loss can cause money problems and increase family:','["free time", "vacations", "stress", "savings"]'::jsonb,2,'Crises affect finances and emotions.','original'),
('127.611.d.3.C',4,'Strong family communication during a crisis can help members cope and stay:','["silent", "divided", "angry", "supportive of one another"]'::jsonb,3,'Support systems reduce harm.','original'),
('127.611.d.3.D',3,'Typical crises for teenagers include peer pressure and school stress, while crises for older adults may include illness or loss. This shows that crises vary by stage of the:','["life cycle", "calendar", "budget", "season"]'::jsonb,0,'Different life stages bring different crises.','original'),
('127.611.d.3.D',4,'The birth of a baby, retirement, and the death of a spouse are events that occur at different stages of the:','["payday", "life cycle", "weekend", "school year"]'::jsonb,1,'Predicting crises helps families prepare.','original'),
('127.611.d.3.E',3,'Heavy workload, money worries, and lack of sleep are factors that can contribute to:','["relaxation", "comfort", "stress", "boredom"]'::jsonb,2,'Stress comes from many sources.','original'),
('127.611.d.3.E',4,'Ongoing stress can affect individuals by causing headaches, trouble sleeping, and problems in:','["street signs", "car engines", "growth charts", "relationships"]'::jsonb,3,'Stress affects health and relationships.','original'),
('127.611.d.3.F',3,'Domestic violence is a pattern of abuse in a relationship that can be physical, emotional, or:','["financial", "random", "helpful", "friendly"]'::jsonb,0,'Abuse takes many forms.','original'),
('127.611.d.3.F',4,'A person who needs help leaving an abusive home can call a hotline or contact a local:','["gym", "shelter", "arcade", "bakery"]'::jsonb,1,'Shelters provide safety and support.','original'),
('127.611.d.3.G',3,'Counselors and social workers are examples of professionals in counseling and mental health:','["trade shows", "airlines", "services", "restaurants"]'::jsonb,2,'Mental health careers help people cope.','original'),
('127.611.d.3.G',4,'A demand of a counseling career is dealing with clients in emotional distress, while a reward is helping them:','["pay more", "avoid all stress", "work less", "improve their lives"]'::jsonb,3,'Helping others is a major reward.','original'),
('127.611.d.3.H',3,'Opening a private counseling practice is an example of an:','["entrepreneurial opportunity", "warranty", "employee handbook", "coupon"]'::jsonb,0,'Entrepreneurs start their own practice.','original'),
('127.611.d.3.H',4,'Counselors usually need a college degree and a state:','["trophy", "license", "uniform", "stamp"]'::jsonb,1,'Licensing proves qualifications.','original'),
('127.611.d.4.A',3,'Food, shelter, safety, and love are among the basic needs of:','["buildings", "tools", "children", "machines"]'::jsonb,2,'All children need these to thrive.','original'),
('127.611.d.4.A',4,'A child who feels secure and loved is more likely to develop healthy emotional:','["fear", "isolation", "anger", "growth"]'::jsonb,3,'Emotional needs are as important as physical ones.','original'),
('127.611.d.4.B',3,'A caregiver keeps small objects out of a toddler''s reach to promote the child''s:','["safety", "boredom", "hunger", "debt"]'::jsonb,0,'Caregivers must prevent hazards.','original'),
('127.611.d.4.B',4,'Reading to a young child, playing games, and talking regularly are caregiver responsibilities that promote:','["dependence", "development", "fear", "decay"]'::jsonb,1,'Interaction supports growth.','original'),
('127.611.d.4.C',3,'Calmly explaining why hitting is wrong and giving the child a safe alternative is a developmentally appropriate guidance technique called:','["harsh punishment", "ignoring", "positive guidance", "bribery"]'::jsonb,2,'Guidance teaches rather than punishes.','original'),
('127.611.d.4.C',4,'A caregiver who expects a two-year-old to sit still for an hour is ignoring what is:','["inconvenient", "expensive", "easy", "developmentally appropriate"]'::jsonb,3,'Expectations should match the child''s age.','original'),
('127.611.d.4.D',3,'Neglect, physical abuse, and emotional abuse are types of:','["child abuse", "play", "child care", "discipline"]'::jsonb,0,'Abuse harms children in different ways.','original'),
('127.611.d.4.D',4,'If you suspect a child is being abused, you should report it to:','["a neighbor only", "child protective services or the police", "no one", "social media"]'::jsonb,1,'Reports can protect the child.','original'),
('127.611.d.4.E',3,'A teacher at a child care center or a pediatric nurse works in early childhood development and:','["mining", "manufacturing", "education", "banking"]'::jsonb,2,'These careers support young children.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
